insert into public.content_prompts (kind, name, rule, angle, brief, say, cover, is_video, sort_order) values
  ('dated', 'New Year''s Day', '{"on":"01-01"}'::jsonb, 'The three things to sort now if you''re selling this year', 'Straight to camera. One thing per point, thirty seconds total.', null, null, false, 0),
  ('dated', 'Burns Night', '{"on":"01-25"}'::jsonb, 'Homes built for a long dinner with friends', 'Kitchen and dining shots only. Warm lamps on, overheads off.', null, null, false, 1),
  ('dated', 'Valentine''s Day', '{"on":"02-14"}'::jsonb, 'The homes we fell in love with this year', 'Three listings, one detail each. Say what made you look twice.', null, null, false, 2),
  ('dated', 'St David''s Day', '{"on":"03-01"}'::jsonb, 'What makes a house feel like it belongs where it stands', 'Exterior shots. Show the street, not just the front door.', null, null, false, 3),
  ('dated', 'International Women''s Day', '{"on":"03-08"}'::jsonb, 'The women who built this agency — and what they''d tell a first-time seller', 'Let them speak to camera themselves. No script.', null, null, false, 4),
  ('dated', 'National Pet Day', '{"on":"04-11"}'::jsonb, 'What buyers with dogs actually look for in a home', 'Garden gates, hard floors, boot rooms. Film them, don''t list them.', null, null, false, 5),
  ('dated', 'Earth Day', '{"on":"04-22"}'::jsonb, 'The efficiency upgrades that actually move an EPC rating', 'Use a real certificate. Before and after, on screen.', null, null, false, 6),
  ('dated', 'St George''s Day', '{"on":"04-23"}'::jsonb, 'Period features worth keeping — and what they add', 'Close-ups: cornicing, fireplaces, sash windows. Hold each shot.', null, null, false, 7),
  ('dated', 'May Day', '{"on":"05-01"}'::jsonb, 'Getting a garden viewing-ready before the bank holiday', 'Film the jobs being done, not a list of them.', null, null, false, 8),
  ('dated', 'World Environment Day', '{"on":"06-05"}'::jsonb, 'Homes that cost less to run — and how you spot one', 'One property, three features, real numbers if you have them.', null, null, false, 9),
  ('dated', 'World Photography Day', '{"on":"08-19"}'::jsonb, 'The difference good photography makes to a sale price', 'Your own before and after. Phone shot beside the professional one.', null, null, false, 10),
  ('dated', 'Back to School', '{"on":"09-01"}'::jsonb, 'What the return to routine teaches you about your space', 'Share how the return to routine can often make people rethink their home. Ask your audience what they''ve learnt about their space over the summer and pair it with a photo of your workspace, local school or a family-friendly home.', null, null, false, 11),
  ('dated', 'International Day of Charity', '{"on":"09-05"}'::jsonb, 'A local cause worth knowing about', 'Shine a light on a local charity, fundraiser or community cause that''s close to your heart. Share why it matters to you and encourage your audience to get involved or support them.', null, null, false, 12),
  ('dated', 'Read a Book Day', '{"on":"09-06"}'::jsonb, 'The book you''d actually recommend', 'Recommend a book you''ve enjoyed, whether it''s business, mindset, property or fiction. A simple photo of the book with a few words about why you''d recommend it works perfectly.', null, null, false, 13),
  ('dated', 'Make Your Bed Day', '{"on":"09-11"}'::jsonb, 'The small routines behind a productive day', 'Talk about the little routines that help you have a productive day. Keep it personal and share a photo of your morning coffee, workspace or something that helps you start the day well.', null, null, false, 14),
  ('dated', 'Positive Thinking Day', '{"on":"09-13"}'::jsonb, 'The outlook that carries you through the job', 'Share a positive mindset that''s helped you in business or life. Keep it authentic and explain how that outlook helps you support your clients every day.', null, null, false, 15),
  ('dated', 'Recycle Day', '{"on":"09-21"}'::jsonb, 'Giving something in the home a second life', 'Highlight a simple way to live more sustainably, whether that''s recycling, upcycling furniture or giving household items a second life. A before-and-after or home inspiration post works well.', null, null, false, 16),
  ('dated', 'Autumn Equinox', '{"on":"09-23"}'::jsonb, 'What you love most about the season turning', 'Mark the first day of autumn by sharing what you love most about the season. Think cosy homes, autumn walks, local scenery or your favourite seasonal traditions.', null, null, false, 17),
  ('dated', 'World''s Biggest Coffee Morning', '{"nth":{"month":9,"weekday":5,"n":-1}}'::jsonb, 'Back a Coffee Morning near you', 'Support Macmillan by promoting a local Coffee Morning or encouraging your audience to get involved. If you''re attending one yourself, share a photo and tag the organisers.', null, null, false, 18),
  ('dated', 'World Tourism Day', '{"on":"09-27"}'::jsonb, 'The one place every local should visit', 'Recommend one place every local should visit, whether it''s a landmark, cafe, beach, walk or hidden gem. Share a photo and explain why it''s worth a visit.', null, null, false, 19),
  ('dated', 'World Podcast Day', '{"on":"09-30"}'::jsonb, 'What you have been listening to', 'Recommend a podcast you''ve enjoyed recently, whether it''s business, property or something completely different. Tell people why you like it and invite them to share their own recommendations.', null, null, false, 20),
  ('dated', 'Black History Month', '{"on":"10-01"}'::jsonb, 'A local story worth telling', 'Celebrate a local person, place or story that has contributed to your community''s history. Keep it respectful, informative and relevant to your local area.', null, null, false, 21),
  ('dated', 'World Smile Day', '{"on":"10-02"}'::jsonb, 'The moment that made you smile this week', 'Share something that''s made you smile recently, whether it''s a client moment, a key handover or something that happened in your community. A genuine story will always outperform a generic quote.', null, null, false, 22),
  ('dated', 'Grandparents'' Day', '{"nth":{"month":10,"weekday":0,"n":1}}'::jsonb, 'The advice you got from someone older and wiser', 'Share a memory, lesson or piece of advice you''ve learnt from a grandparent or older family member. A personal photo works well if you''re comfortable sharing one.', null, null, false, 23),
  ('dated', 'World Mental Health Day', '{"on":"10-10"}'::jsonb, 'How you actually switch off', 'Talk honestly about looking after your wellbeing. Share a habit, routine or place that helps you switch off and encourage others to do the same.', null, null, false, 24),
  ('dated', 'Coffee Week', '{"on":"10-12"}'::jsonb, 'Your local, and your usual order', 'Give a shout-out to your favourite local coffee shop or cafe. Share what you always order and encourage your audience to support local businesses.', null, null, false, 25),
  ('dated', 'Clocks Go Back', '{"nth":{"month":10,"weekday":0,"n":-1}}'::jsonb, 'Making a home feel warm when the evenings draw in', 'Mark the arrival of darker evenings with autumn home inspiration. Share simple ways to make your home feel warm, cosy and inviting during the colder months.', null, null, false, 26),
  ('dated', 'Pumpkin Day', '{"on":"10-26"}'::jsonb, 'Your pumpkin, or the patch you found it at', 'Show off your pumpkin carving, favourite autumn decoration or a local pumpkin patch. Keep it light-hearted and seasonal.', null, null, false, 27),
  ('dated', 'Halloween', '{"on":"10-31"}'::jsonb, 'Join in without trying too hard', 'Join in with Halloween by sharing a decorated office, carved pumpkin or a fun community event. If appropriate, ask your audience to vote for their favourite costume or pumpkin.', null, null, false, 28),
  ('dated', 'Movember', '{"on":"11-01"}'::jsonb, 'Why men''s health is worth a month', 'If you''re taking part, share why you''re supporting Movember and the importance of men''s health. If not, help raise awareness by sharing where people can find out more.', null, null, false, 29),
  ('dated', 'Bonfire Night', '{"on":"11-05"}'::jsonb, 'Where to watch, and a word about pets', 'Share your favourite local fireworks display or Bonfire Night event. If you have pets, include a reminder about keeping them safe during fireworks.', null, null, false, 30),
  ('dated', 'Remembrance Sunday', '{"nth":{"month":11,"weekday":0,"n":2}}'::jsonb, 'A simple message of remembrance', 'Mark the day respectfully with a simple message of remembrance. Keep the focus on reflection rather than promotion.', null, null, false, 31),
  ('dated', 'Armistice Day', '{"on":"11-11"}'::jsonb, 'Observe the silence', 'Observe the two-minute silence and share a respectful message recognising those who served. Avoid promotional content alongside this post.', null, null, false, 32),
  ('dated', 'World Kindness Day', '{"on":"11-13"}'::jsonb, 'A small kindness worth passing on', 'Share a small act of kindness you''ve experienced or encourage your audience to support someone in their local community. Simple stories often resonate the most.', null, null, false, 33),
  ('dated', 'International Men''s Day', '{"on":"11-19"}'::jsonb, 'The men who taught you something', 'Celebrate positive male role models, whether that''s a family member, colleague or friend. Share what you''ve learnt from them or why you appreciate them.', null, null, false, 34),
  ('dated', 'Black Friday', '{"nth":{"month":11,"weekday":4,"n":4,"offset":1}}'::jsonb, 'Independents worth your money this week', 'Instead of focusing on discounts, share your favourite local independent businesses that deserve support during the busy shopping season.', null, null, false, 35),
  ('dated', 'Small Business Saturday', '{"nth":{"month":11,"weekday":4,"n":4,"offset":2}}'::jsonb, 'The independent you would send a friend to', 'Shine a light on an independent business you love. Share why you''d recommend them and encourage your audience to shop local where they can.', null, null, false, 36),
  ('dated', 'St Andrew''s Day', '{"on":"11-30"}'::jsonb, 'What makes your patch worth living in', 'If you''re based in Scotland, celebrate what makes your local area special. If not, share your favourite Scottish destination, memory or tradition.', null, null, false, 37),
  ('dated', 'First Day of Advent', '{"on":"12-01"}'::jsonb, 'The one thing you are looking forward to', 'Mark the countdown to Christmas by sharing one thing you''re looking forward to this festive season. A festive workspace or local decoration makes a great visual.', null, null, false, 38),
  ('dated', 'International Volunteer Day', '{"on":"12-05"}'::jsonb, 'The volunteers who hold your area together', 'Recognise the volunteers who make a difference in your local community or share a cause you''ve supported yourself.', null, null, false, 39),
  ('dated', 'Christmas Card Day', '{"on":"12-09"}'::jsonb, 'Cards, and the people who make them', 'Share a photo of your Christmas cards, your team''s festive setup or encourage people to support local card makers this Christmas.', null, null, false, 40),
  ('dated', 'Christmas Jumper Day', '{"on":"12-10"}'::jsonb, 'Wear the jumper, ask for theirs', 'Join in by wearing your favourite Christmas jumper and encourage your audience to do the same. If you''re fundraising, let people know how they can support you.', null, null, false, 41),
  ('dated', 'First Day of Winter', '{"on":"12-21"}'::jsonb, 'A cosy home, or a frosty morning', 'Celebrate the start of winter with a cosy home, frosty morning or beautiful local landscape. Ask your audience what they love most about the season.', null, null, false, 42),
  ('dated', 'Christmas Eve', '{"on":"12-24"}'::jsonb, 'Thank the people who made the year', 'Share a warm festive message thanking your clients, followers and local community for their support throughout the year.', null, null, false, 43),
  ('dated', 'Christmas Day', '{"on":"12-25"}'::jsonb, 'Merry Christmas, and nothing else', 'Wish everyone a Merry Christmas with a simple, heartfelt message. Keep the focus on spending time with loved ones and enjoying the day.', null, null, false, 44),
  ('dated', 'Boxing Day', '{"on":"12-26"}'::jsonb, 'Walk, leftovers, or the sofa?', 'Ask your audience how they''re spending Boxing Day, whether it''s a walk, leftovers or a day on the sofa. Keep it relaxed and conversational.', null, null, false, 45),
  ('dated', 'New Year''s Eve', '{"on":"12-31"}'::jsonb, 'The year in one highlight and one lesson', 'Reflect on the year, share a highlight or lesson you''ve learnt and thank your clients and community for their support. End by wishing everyone a happy New Year.', null, null, false, 46),
  ('dated', 'World Book Day', '{"nth":{"month":3,"weekday":4,"n":1}}'::jsonb, 'Reading corners: the small spaces that sell a family home', 'Find the nook in your current listings. One shot each.', null, null, false, 47),
  ('evergreen', null, null, 'Three questions buyers nearly always ask at a viewing', 'Talk straight to camera. Put each question on screen as you answer it.', 'Start with the first question immediately. Answer all three in one or two sentences each, using what you hear from real buyers.', 'The 3 questions buyers always ask. Use your face or a strong property shot behind the text.', true, 0),
  ('evergreen', null, null, 'The room buyers remember most, and why', 'Use one strong room photo. In the caption, explain why this room stands out and what buyers tend to respond to.', null, null, false, 1),
  ('evergreen', null, null, '3 small changes that can make a home feel more viewing-ready', 'Create a simple 4-slide carousel: hook, then one practical change per slide. Keep the advice realistic, low-cost and easy to action.', null, null, false, 2),
  ('evergreen', null, null, 'Come with me on a 60-second property tour', 'Walk through one current listing. Start with the strongest feature rather than automatically starting at the front door.', 'Open with the reason someone should keep watching, then take viewers through 3 to 5 standout features. Finish with the area, price and CTA.', 'Use the strongest property shot with “60-second tour” and the area or property type.', true, 3),
  ('evergreen', null, null, '5 things buyers notice before the viewing really starts', 'Turn this into a 6-slide carousel: hook plus five details such as kerb appeal, entrance, light, smell and first impression. Add your own local experience.', null, null, false, 4),
  ('evergreen', null, null, 'What actually happens before your property goes live', 'Film short behind-the-scenes clips while preparing a real listing: photos, measurements, floorplan, write-up, calls or final checks.', 'Use a simple voiceover or talk while you work. Explain what is happening and why each step matters to the launch.', 'A candid behind-the-scenes frame with “Before your property goes live”.', true, 5),
  ('evergreen', null, null, 'Moving here? Save these 3 local spots', 'Create a local carousel featuring three places people genuinely use: coffee, green space, schools, shops, walks or weekend spots. Make it specific to your patch.', null, null, false, 6),
  ('evergreen', null, null, 'Coming soon: give buyers one reason to watch this space', 'Use one strong detail shot from an upcoming listing. Tease one feature, the property type or the area without revealing everything. End with a CTA to register interest.', null, null, false, 7),
  ('evergreen', null, null, 'What an estate agent actually does in a day', 'Capture 4 to 6 honest moments across a normal working day. Include the less polished parts, not just viewings and keys.', 'Use timestamps or a short voiceover to explain each moment. Keep it natural and specific to your actual day.', 'Use a candid frame from the day with “A day in estate agency”.', true, 8),
  ('evergreen', null, null, 'Why the highest valuation is not always the best valuation', 'Create a 4-slide educational carousel: the tempting number, the risk of overpricing, what good pricing should consider, and your advice to sellers. Avoid attacking competitors.', null, null, false, 9),
  ('evergreen', null, null, 'Property myth or fact? Pick one sellers still believe', 'Choose one common seller myth and build a simple 3-slide carousel: myth, reality, what the seller should do instead. Use a myth you genuinely hear in your area.', null, null, false, 10),
  ('evergreen', null, null, 'A result worth sharing, and what made the difference', 'Share a genuine client result using a sold photo, testimonial or simple branded graphic. Add the useful context: the challenge, what you did and the outcome.', null, null, false, 11),
  ('evergreen', null, null, 'What is actually happening in your local property market?', 'Give a short local market update using one or two useful data points. Explain what they mean rather than reading out a list of statistics.', 'Lead with the most useful takeaway for local sellers or buyers. Give the number, explain the context, then say what you would do with that information.', 'Use the area name plus one headline figure or takeaway. Keep the cover simple.', true, 12),
  ('evergreen', null, null, 'First-time buyer? Sort this before you start offering', 'Create a simple educational post around one practical first-time buyer step, such as agreement in principle, deposit position, solicitor or total buying costs. Keep it focused on one topic.', null, null, false, 13),
  ('evergreen', null, null, 'The story behind this sale', 'Use a sold property as a mini case study. Structure the caption or carousel around the starting point, the challenge, what you did and the result. Use real figures only where you can substantiate them.', null, null, false, 14),
  ('evergreen', null, null, '3 quick jobs to do before your next viewing', 'Film three simple viewing-prep jobs being done. Choose practical actions a seller could complete quickly.', 'Name each job as you do it and explain in one sentence why it helps the viewing experience. Keep the pace quick.', '“3 jobs before a viewing” over the strongest finished shot.', true, 15);
